db.js.content:
import { MongoClient } from "mongodb";
import { cfg } from "./config.js";
import { log, safeErr } from "./log.js";

let client = null;
let db = null;

export async function connectDb() {
  if (db) return db;

  if (!cfg.MONGODB_URI) {
    throw new Error("MONGODB_URI is required for persistent wallet storage.");
  }

  try {
    client = new MongoClient(cfg.MONGODB_URI, {
      ignoreUndefined: true,
      maxPoolSize: 10,
    });

    await client.connect();
    db = client.db();
    log.info("db.connected", { mongodbUriSet: true });
    return db;
  } catch (err) {
    log.error("db.connect.failure", {
      collection: "database",
      operation: "connect",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function getDb() {
  return db || connectDb();
}

export async function ensureIndexes() {
  const database = await getDb();

  try {
    await database.collection("users").createIndex({ telegramUserId: 1 }, { unique: true });
    await database.collection("users").createIndex({ username: 1 }, { sparse: true });
    await database.collection("wallets").createIndex({ userId: 1 }, { unique: true });
    await database.collection("transactions").createIndex({ userId: 1, createdAt: -1 });
    await database.collection("transactions").createIndex({ status: 1, createdAt: -1 });
    log.info("db.indexes.ready", { collections: ["users", "wallets", "transactions"] });
  } catch (err) {
    log.error("db.indexes.failure", {
      collection: "multiple",
      operation: "ensureIndexes",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function closeDb() {
  if (!client) return;
  await client.close();
  client = null;
  db = null;
}

log.js.content:
export function safeErr(err) {
  return err?.response?.data?.error?.message ||
    err?.response?.data?.message ||
    err?.message ||
    String(err);
}

function emit(level, message, meta = {}) {
  const row = {
    level,
    message,
    ts: new Date().toISOString(),
    ...meta,
  };

  const line = JSON.stringify(row);
  if (level === "error") console.error(line);
  else if (level === "warn") console.warn(line);
  else console.log(line);
}

export const log = {
  info: (message, meta) => emit("info", message, meta),
  warn: (message, meta) => emit("warn", message, meta),
  error: (message, meta) => emit("error", message, meta),
};

telegramAuth.js.content:
import crypto from "node:crypto";

export function verifyTelegramInitData(initData, botToken, maxAgeSeconds = 86400) {
  const raw = String(initData || "");
  if (!raw) return { ok: false, error: "MISSING_INIT_DATA" };
  if (!botToken) return { ok: false, error: "MISSING_BOT_TOKEN" };

  const params = new URLSearchParams(raw);
  const hash = params.get("hash") || "";
  if (!hash) return { ok: false, error: "MISSING_HASH" };

  params.delete("hash");

  const pairs = [];
  for (const [key, value] of params.entries()) {
    pairs.push(`${key}=${value}`);
  }
  pairs.sort();

  const dataCheckString = pairs.join("\n");
  const secretKey = crypto.createHmac("sha256", "WebAppData").update(botToken).digest();
  const calculated = crypto.createHmac("sha256", secretKey).update(dataCheckString).digest("hex");

  const left = Buffer.from(calculated, "hex");
  const right = Buffer.from(hash, "hex");
  if (left.length !== right.length || !crypto.timingSafeEqual(left, right)) {
    return { ok: false, error: "BAD_HASH" };
  }

  const authDate = Number(params.get("auth_date") || 0);
  if (maxAgeSeconds > 0 && authDate > 0) {
    const age = Math.floor(Date.now() / 1000) - authDate;
    if (age > maxAgeSeconds) return { ok: false, error: "INIT_DATA_EXPIRED" };
  }

  let user = null;
  try {
    user = JSON.parse(params.get("user") || "null");
  } catch {
    user = null;
  }

  if (!user?.id) return { ok: false, error: "MISSING_USER" };

  return {
    ok: true,
    user,
    authDate,
  };
}

server.js.content:
import express from "express";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { verifyTelegramInitData } from "./lib/telegramAuth.js";
import { log, safeErr } from "./lib/log.js";
import { getWalletSummary, listTransactions } from "./services/wallet.js";

const currentDir = path.dirname(fileURLToPath(import.meta.url));

function getInitData(req) {
  return String(req.get("x-telegram-init-data") || req.body?.initData || "");
}

function authenticateMiniApp(req, cfg) {
  return verifyTelegramInitData(getInitData(req), cfg.TELEGRAM_BOT_TOKEN);
}

export async function startServer(cfg) {
  const app = express();
  app.disable("x-powered-by");
  app.use(express.json({ limit: "256kb" }));

  app.get("/health", (_req, res) => {
    res.json({
      ok: true,
      telegramTokenSet: Boolean(cfg.TELEGRAM_BOT_TOKEN),
      mongodbUriSet: Boolean(cfg.MONGODB_URI),
    });
  });

  app.get("/api/wallet/summary", async (req, res) => {
    const auth = authenticateMiniApp(req, cfg);
    if (!auth.ok) return res.status(401).json({ ok: false, error: "Unable to verify Telegram session." });

    try {
      const summary = await getWalletSummary(auth.user);
      return res.json({ ok: true, ...summary });
    } catch (err) {
      log.error("api.wallet.summary.failure", {
        collection: "wallets",
        operation: "GET /api/wallet/summary",
        err: safeErr(err),
      });
      return res.status(500).json({ ok: false, error: "Unable to load wallet right now." });
    }
  });

  app.get("/api/wallet/transactions", async (req, res) => {
    const auth = authenticateMiniApp(req, cfg);
    if (!auth.ok) return res.status(401).json({ ok: false, error: "Unable to verify Telegram session." });

    try {
      const limit = Number(req.query.limit || 25);
      const transactions = await listTransactions(auth.user, limit);
      return res.json({ ok: true, transactions });
    } catch (err) {
      log.error("api.wallet.transactions.failure", {
        collection: "transactions",
        operation: "GET /api/wallet/transactions",
        err: safeErr(err),
      });
      return res.status(500).json({ ok: false, error: "Unable to load transactions right now." });
    }
  });

  const distDir = path.join(currentDir, "..", "webapp", "dist");
  const indexHtml = path.join(distDir, "index.html");

  function sendIndex(_req, res) {
    if (fs.existsSync(indexHtml)) return res.sendFile(indexHtml);
    return res.status(200).send("Points Wallet web app is not built yet. Run npm run build:webapp.");
  }

  if (fs.existsSync(distDir)) {
    app.use("/app", express.static(distDir));
  }

  app.get("/app", sendIndex);
  app.get("/app/*splat", sendIndex);
  app.get("/", (_req, res) => res.redirect("/app"));

  await new Promise((resolve) => {
    app.listen(cfg.PORT, () => resolve(null));
  });

  log.info("server.started", {
    port: cfg.PORT,
    miniAppUrlSet: Boolean(cfg.MINI_APP_URL),
  });
}

wallet.js.content:
import { getDb } from "../lib/db.js";
import { log, safeErr } from "../lib/log.js";

function asTelegramUserId(value) {
  return String(value || "").trim();
}

function cleanMutableUser(input = {}) {
  const mutable = {
    telegramUserId: asTelegramUserId(input.id || input.telegramUserId),
    username: input.username || "",
    firstName: input.first_name || input.firstName || "",
    lastName: input.last_name || input.lastName || "",
    languageCode: input.language_code || input.languageCode || "",
    updatedAt: new Date(),
    lastSeenAt: new Date(),
  };

  delete mutable._id;
  delete mutable.createdAt;
  return mutable;
}

export async function ensureWalletForTelegramUser(telegramUser = {}) {
  const telegramUserId = asTelegramUserId(telegramUser.id || telegramUser.telegramUserId);
  if (!telegramUserId) throw new Error("Telegram user id is required.");

  const database = await getDb();
  const users = database.collection("users");
  const wallets = database.collection("wallets");
  const now = new Date();

  try {
    const mutableUser = cleanMutableUser({ ...telegramUser, telegramUserId });

    await users.updateOne(
      { telegramUserId },
      {
        $setOnInsert: {
          createdAt: now,
          status: "active",
          platform: "telegram",
        },
        $set: mutableUser,
      },
      { upsert: true }
    );

    await wallets.updateOne(
      { userId: telegramUserId },
      {
        $setOnInsert: {
          userId: telegramUserId,
          pointsBalance: 0,
          totalEarned: 0,
          totalSpent: 0,
          transactionCount: 0,
          createdAt: now,
        },
        $set: {
          updatedAt: now,
        },
      },
      { upsert: true }
    );

    const [user, wallet] = await Promise.all([
      users.findOne({ telegramUserId }),
      wallets.findOne({ userId: telegramUserId }),
    ]);

    return { user, wallet };
  } catch (err) {
    log.error("wallet.ensure.failure", {
      collection: "users,wallets",
      operation: "ensureWalletForTelegramUser",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function getWalletSummary(telegramUser) {
  const telegramUserId = asTelegramUserId(telegramUser?.id || telegramUser?.telegramUserId);
  if (!telegramUserId) throw new Error("Telegram user id is required.");

  try {
    const { user, wallet } = await ensureWalletForTelegramUser(telegramUser);
    const database = await getDb();
    const latest = await database
      .collection("transactions")
      .find({ userId: telegramUserId })
      .sort({ })
      .limit(1)
      .toArray();

    return {
      user: {
        telegramUserId,
        username: user?.username || "",
        firstName: user?.firstName || "",
        lastName: user?.lastName || "",
      },
      wallet: {
        pointsBalance: wallet?.pointsBalance || 0,
        totalEarned: wallet?.totalEarned || 0,
        totalSpent: wallet?.totalSpent || 0,
        transactionCount: wallet?.transactionCount || 0,
        latestActivity: latest[0] || null,
      },
    };
  } catch (err) {
    log.error("wallet.summary.failure", {
      collection: "wallets",
      operation: "getWalletSummary",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function listTransactions(telegramUser, limit = 25) {
  const telegramUserId = asTelegramUserId(telegramUser?.id || telegramUser?.telegramUserId);
  if (!telegramUserId) throw new Error("Telegram user id is required.");

  const safeLimit = Math.max(1, Math.min(Number(limit || 25), 50));

  try {
    await ensureWalletForTelegramUser(telegramUser);
    const database = await getDb();
    const docs = await database
      .collection("transactions")
      .find({ userId: telegramUserId })
      .sort({ createdAt: -1 })
      .limit(safeLimit)
      .toArray();

    return docs.map((doc) => ({
      id: String(doc._id),
      type: doc.type || "adjustment",
      amount: Number(doc.amount || 0),
      description: doc.description || "Points activity",
      status: doc.status || "completed",
      createdAt: doc.createdAt,
      updatedAt: doc.updatedAt,
    }));
  } catch (err) {
    log.error("wallet.transactions.failure", {
      collection: "transactions",
      operation: "listTransactions",
      err: safeErr(err),
    });
    throw err;
  }
}

App.jsx.content:
import React, { useCallback, useEffect, useMemo, useState } from "react";

function getTelegramWebApp() {
  return window?.Telegram?.WebApp || null;
}

function applyTheme(tg) {
  const p = tg?.themeParams || {};
  const bg = p.bg_color || "#111827";
  const text = p.text_color || "#f9fafb";
  const hint = p.hint_color || "#9ca3af";
  const card = p.secondary_bg_color || "rgba(255,255,255,0.08)";
  const accent = p.button_color || "#7c3aed";
  const buttonText = p.button_text_color || "#ffffff";

  document.documentElement.style.setProperty("--bg", bg);
  document.documentElement.style.setProperty("--text", text);
  document.documentElement.style.setProperty("--muted", hint);
  document.documentElement.style.setProperty("--card", card);
  document.documentElement.style.setProperty("--accent", accent);
  document.documentElement.style.setProperty("--buttonText", buttonText);
  document.body.style.background = bg;
  document.body.style.color = text;
}

function formatDate(value) {
  if (!value) return "No activity yet";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "No activity yet";
  return date.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

function Skeleton() {
  return (
    <div className="space-y-4 animate-pulse">
      <div className="h-28 rounded-3xl bg-white/10" />
      <div className="h-40 rounded-3xl bg-white/10" />
      <div className="grid grid-cols-3 gap-3">
        <div className="h-20 rounded-2xl bg-white/10" />
        <div className="h-20 rounded-2xl bg-white/10" />
        <div className="h-20 rounded-2xl bg-white/10" />
      </div>
    </div>
  );
}

function Card({ children, className = "" }) {
  return <section className={`card ${className}`}>{children}</section>;
}

function Stat({ label, value }) {
  return (
    <div className="card min-h-[84px] justify-center">
      <div className="text-xs" style={{ color: "var(--muted)" }}>{label}</div>
      <div className="mt-1 text-lg font-bold">{value}</div>
    </div>
  );
}

function TransactionRow({ tx }) {
  const isDebit = tx.type === "spend";
  const amount = Number(tx.amount || 0);
  return (
    <div className="flex items-center justify-between gap-3 rounded-2xl border border-white/10 bg-white/[0.04] p-3">
      <div className="min-w-0">
        <div className="flex items-center gap-2">
          <span className="rounded-full px-2 py-1 text-[11px] font-semibold capitalize bg-white/10">{tx.type}</span>
          <span className="text-[11px] capitalize" style={{ color: "var(--muted)" }}>{tx.status}</span>
        </div>
        <div className="mt-2 truncate text-sm font-semibold">{tx.description || "Points activity"}</div>
        <div className="mt-1 text-xs" style={{ color: "var(--muted)" }}>{formatDate(tx.createdAt)}</div>
      </div>
      <div className={`shrink-0 text-right text-base font-bold ${isDebit ? "text-rose-300" : "text-emerald-300"}`}>
        {isDebit ? "-" : "+"}{Math.abs(amount)}
      </div>
    </div>
  );
}

export default function App() {
  const tg = useMemo(() => getTelegramWebApp(), []);
  const [tab, setTab] = useState("dashboard");
  const [status, setStatus] = useState("loading");
  const [error, setError] = useState("");
  const [summary, setSummary] = useState(null);
  const [transactions, setTransactions] = useState([]);

  useEffect(() => {
    try {
      tg?.ready?.();
      tg?.expand?.();
      tg?.disableVerticalSwipes?.();
      tg?.setHeaderColor?.(tg?.themeParams?.bg_color || "#111827");
      tg?.setBackgroundColor?.(tg?.themeParams?.bg_color || "#111827");
      applyTheme(tg);
      tg?.onEvent?.("themeChanged", () => applyTheme(tg));
    } catch {
      applyTheme(null);
    }
  }, [tg]);

  const loadWallet = useCallback(async () => {
    const initData = tg?.initData || "";
    if (!initData) {
      setStatus("error");
      setError("Open Points Wallet from Telegram to view private wallet data.");
      return;
    }

    try {
      setStatus("loading");
      setError("");

      const headers = { "x-telegram-init-data": initData };
      const [summaryResp, txResp] = await Promise.all([
        fetch("/api/wallet/summary", { headers }),
        fetch("/api/wallet/transactions?limit=50", { headers }),
      ]);

      const summaryJson = await summaryResp.json().catch(() => null);
      const txJson = await txResp.json().catch(() => null);

      if (!summaryResp.ok || !summaryJson?.ok) throw new Error(summaryJson?.error || "summary_failed");
      if (!txResp.ok || !txJson?.ok) throw new Error(txJson?.error || "transactions_failed");

      setSummary(summaryJson);
      setTransactions(txJson.transactions || []);
      setStatus("ready");
    } catch {
      setStatus("error");
      setError("We could not load your wallet. Please retry in a moment.");
    }
  }, [tg]);

  useEffect(() => {
    loadWallet();
  }, [loadWallet]);

  const user = summary?.user;
  const wallet = summary?.wallet;
  const displayName = [user?.firstName, user?.lastName].filter(Boolean).join(" ") || user?.username || "there";
  const latest = wallet?.latestActivity;

  return (
    <main className="min-h-screen overflow-x-hidden px-4 pt-4 pb-8 safe-bottom">
      <div className="mx-auto max-w-md space-y-4">
        <header className="flex items-center justify-between gap-3">
          <div>
            <div className="text-2xl font-black tracking-tight">Points Wallet</div>
            <div className="text-sm" style={{ color: "var(--muted)" }}>Balance and activity dashboard</div>
          </div>
          <button className="touch-button rounded-2xl px-4 text-sm font-bold" onClick={loadWallet} style={{ background: "var(--accent)", color: "var(--buttonText)" }}>
            Refresh
          </button>
        </header>

        {status === "loading" ? <Skeleton /> : null}

        {status === "error" ? (
          <Card className="text-center">
            <div className="text-lg font-bold">Wallet unavailable</div>
            <p className="mt-2 text-sm" style={{ color: "var(--muted)" }}>{error}</p>
            <button className="touch-button mt-4 w-full rounded-2xl font-bold" onClick={loadWallet} style={{ background: "var(--accent)", color: "var(--buttonText)" }}>
              Retry
            </button>
          </Card>
        ) : null}

        {status === "ready" ? (
          <>
            <Card className="bg-gradient-to-br from-violet-500/30 to-fuchsia-500/10">
              <div className="text-sm" style={{ color: "var(--muted)" }}>Welcome back</div>
              <div className="mt-1 text-2xl font-black">Hi, {displayName}</div>
              <div className="mt-3 text-sm" style={{ color: "var(--muted)" }}>Your wallet is synced with your Telegram account.</div>
            </Card>

            <div className="grid grid-cols-2 gap-2 rounded-2xl bg-white/10 p-1">
              <button className={`touch-button rounded-xl text-sm font-bold ${tab === "dashboard" ? "bg-white text-gray-950" : "text-white"}`} onClick={() => setTab("dashboard")}>Dashboard</button>
              <button className={`touch-button rounded-xl text-sm font-bold ${tab === "transactions" ? "bg-white text-gray-950" : "text-white"}`} onClick={() => setTab("transactions")}>Transactions</button>
            </div>

            {tab === "dashboard" ? (
              <div className="space-y-4">
                <Card>
                  <div className="text-sm" style={{ color: "var(--muted)" }}>Total points</div>
                  <div className="mt-2 text-5xl font-black tracking-tight">{wallet?.pointsBalance || 0}</div>
                  <div className="mt-4 rounded-2xl bg-white/10 p-3 text-sm">
                    Latest activity: {latest ? `${latest.description || "Points activity"} · ${formatDate(latest.createdAt)}` : "No transactions yet"}
                  </div>
                </Card>

                <div className="grid grid-cols-3 gap-3">
                  <Stat label="Earned" value={wallet?.totalEarned || 0} />
                  <Stat label="Spent" value={wallet?.totalSpent || 0} />
                  <Stat label="Records" value={wallet?.transactionCount || 0} />
                </div>

                <Card>
                  <div className="mb-3 flex items-center justify-between">
                    <div className="font-bold">Recent transactions</div>
                    <button className="text-sm font-semibold" onClick={() => setTab("transactions")} style={{ color: "var(--accent)" }}>View all</button>
                  </div>
                  {transactions.length ? (
                    <div className="space-y-2">{transactions.slice(0, 3).map((tx) => <TransactionRow key={tx.id} tx={tx} />)}</div>
                  ) : (
                    <div className="rounded-2xl border border-dashed border-white/15 p-5 text-center text-sm" style={{ color: "var(--muted)" }}>No transactions yet. Your activity will appear here.</div>
                  )}
                </Card>
              </div>
            ) : (
              <Card>
                <div className="mb-3 text-lg font-bold">Transaction history</div>
                {transactions.length ? (
                  <div className="space-y-2">{transactions.map((tx) => <TransactionRow key={tx.id} tx={tx} />)}</div>
                ) : (
                  <div className="rounded-2xl border border-dashed border-white/15 p-6 text-center">
                    <div className="font-bold">No transactions yet</div>
                    <p className="mt-2 text-sm" style={{ color: "var(--muted)" }}>When you earn, spend, or receive adjustments, they will show up here.</p>
                  </div>
                )}
              </Card>
            )}
          </>
        ) : null}
      </div>
    </main>
  );
}

