import "dotenv/config";
import { run } from "@grammyjs/runner";
import { log, safeErr } from "./lib/log.js";

process.on("unhandledRejection", (err) => {
  log.error("process.unhandledRejection", { err: safeErr(err) });
  process.exit(1);
});

process.on("uncaughtException", (err) => {
  log.error("process.uncaughtException", { err: safeErr(err) });
  process.exit(1);
});

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

let pollingStarted = false;

async function startPolling(bot) {
  if (pollingStarted) return;
  pollingStarted = true;

  let delayMs = 2000;

  while (true) {
    try {
      log.info("telegram.polling.starting");
      await bot.api.deleteWebhook({ drop_pending_updates: true });

      const runner = run(bot, {
        runner: {
          fetch: {
            allowed_updates: ["message"],
          },
          sink: {
            concurrency: 1,
          },
        },
      });

      log.info("telegram.polling.started");
      await runner.task();
      delayMs = 2000;
    } catch (err) {
      const message = safeErr(err);
      log.error("telegram.polling.failure", {
        err: message,
        conflict: message.includes("409") || message.toLowerCase().includes("conflict"),
      });
      await sleep(delayMs);
      delayMs = Math.min(delayMs * 2, 20000);
    }
  }
}

async function boot() {
  try {
    log.info("boot.start");

    const { cfg } = await import("./lib/config.js");
    log.info("config.loaded", {
      telegramTokenSet: Boolean(cfg.TELEGRAM_BOT_TOKEN),
      mongodbUriSet: Boolean(cfg.MONGODB_URI),
      appBaseUrlSet: Boolean(cfg.APP_BASE_URL),
      portSet: Boolean(cfg.PORT),
    });

    if (!cfg.TELEGRAM_BOT_TOKEN) {
      log.error("config.missing", { key: "TELEGRAM_BOT_TOKEN" });
      console.error("TELEGRAM_BOT_TOKEN is required. Add it in your environment and redeploy.");
      process.exit(1);
    }

    if (!cfg.MONGODB_URI) {
      log.error("config.missing", { key: "MONGODB_URI" });
      console.error("MONGODB_URI is required for Points Wallet persistence.");
      process.exit(1);
    }

    const { connectDb, ensureIndexes } = await import("./lib/db.js");
    const { startServer } = await import("./server.js");
    const { createBot } = await import("./bot.js");

    await connectDb();
    await ensureIndexes();
    await startServer(cfg);

    const bot = await createBot(cfg);
    await bot.init();
    log.info("telegram.bot.ready", { botUsernameSet: Boolean(bot.botInfo?.username) });

    setInterval(() => {
      const m = process.memoryUsage();
      log.info("mem", {
        rssMB: Math.round(m.rss / 1e6),
        heapUsedMB: Math.round(m.heapUsed / 1e6),
      });
    }, 60000).unref();

    startPolling(bot).catch((err) => {
      log.error("telegram.polling.loop.crashed", { err: safeErr(err) });
      process.exit(1);
    });

    log.info("boot.success");
  } catch (err) {
    log.error("boot.failure", { err: safeErr(err), code: err?.code || "" });
    process.exit(1);
  }
}

boot();

config.js.content:
function toPort(value) {
  const n = Number(value || 4000);
  return Number.isFinite(n) && n > 0 ? n : 4000;
}

function cleanBaseUrl(value) {
  return String(value || "")
    .replace(/\/+$/, "")
    .replace(/\/app$/i, "");
}

const PORT = toPort(process.env.PORT || 4000);

const managedBase = (
  process.env.RENDER_EXTERNAL_URL ||
  process.env.PUBLIC_BASE_URL ||
  process.env.WEBAPP_URL ||
  process.env.WEB_APP_URL ||
  process.env.PUBLIC_URL ||
  ""
).replace(/\/+$/, "").replace(/\/app$/i, "");

const appBase = cleanBaseUrl(
  managedBase ||
    process.env.APP_BASE_URL ||
    `http://localhost:${PORT}`
);

export const cfg = {
  TELEGRAM_BOT_TOKEN: process.env.TELEGRAM_BOT_TOKEN || "",
  MONGODB_URI: process.env.MONGODB_URI || "",
  PORT,
  PUBLIC_BASE_URL: managedBase,
  APP_BASE_URL: appBase,
  MINI_APP_URL: appBase ? `${appBase}/app` : "",
};

db.js.content:
import { MongoClient } from "mongodb";
import { cfg } from "./config.js";
import { log, safeErr } from "./log.js";

let client = null;
let db = null;

export async function connectDb() {
  if (db) return db;

  if (!cfg.MONGODB_URI) {
    throw new Error("MONGODB_URI is required for persistent wallet storage.");
  }

  try {
    client = new MongoClient(cfg.MONGODB_URI, {
      ignoreUndefined: true,
      maxPoolSize: 10,
    });

    await client.connect();
    db = client.db();
    log.info("db.connected", { mongodbUriSet: true });
    return db;
  } catch (err) {
    log.error("db.connect.failure", {
      collection: "database",
      operation: "connect",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function getDb() {
  return db || connectDb();
}

export async function ensureIndexes() {
  const database = await getDb();

  try {
    await database.collection("users").createIndex({ telegramUserId: 1 }, { unique: true });
    await database.collection("users").createIndex({ username: 1 }, { sparse: true });
    await database.collection("wallets").createIndex({ userId: 1 }, { unique: true });
    await database.collection("transactions").createIndex({ userId: 1, createdAt: -1 });
    await database.collection("transactions").createIndex({ status: 1, createdAt: -1 });
    log.info("db.indexes.ready", { collections: ["users", "wallets", "transactions"] });
  } catch (err) {
    log.error("db.indexes.failure", {
      collection: "multiple",
      operation: "ensureIndexes",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function closeDb() {
  if (!client) return;
