@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --bg: #111827;
  --text: #f9fafb;
  --muted: #9ca3af;
  --card: rgba(255, 255, 255, 0.08);
  --accent: #7c3aed;
  --buttonText: #ffffff;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
